from pathlib import Path
import json, html
from generate_llms import generate_llms
r=Path(__file__).resolve().parents[1]
p=r/'public'
a=p/'ai-coding'
a.mkdir(exist_ok=True)
v=json.loads((r/'data/ai-videos.json').read_text(encoding='utf-8'))
D='https://thetips4you.in'
def e(x): return html.escape(str(x),quote=True)
def link(x): return '/ai-coding/'+x['slug']+'/' if x['watch'] else 'https://www.youtube.com/watch?v='+x['id']
def head(title,description,canonical,image=None,schema=None):
    image=image or D+'/og-cover.png'
    ld='<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False).replace('<','\\u003c')+'</script>' if schema else ''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index,follow,max-video-preview:-1"><title>{e(title)}</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{e(canonical)}"><link rel="describedby" href="/llms.txt" type="text/markdown"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><meta name="theme-color" content="#111310"><meta property="og:type" content="website"><meta property="og:site_name" content="Thetips4you"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{e(canonical)}"><meta property="og:image" content="{e(image)}"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/ai-coding/style.css">{ld}</head><body><a class="skip" href="#main">Skip to content</a><header><div class="wrap head"><a class="brand" href="/">thetips<span>4</span>you.</a><nav aria-label="Main navigation"><a href="/">Home</a><a href="/ai-coding/">AI coding</a><a href="/courses/">Full courses</a></nav><a class="channel" href="https://www.youtube.com/@Thetips4you" target="_blank" rel="noopener noreferrer">YouTube ↗</a></div></header><main id="main">'''
def foot(): return '<footer><div class="wrap foot"><a class="brand" href="/">thetips<span>4</span>you.</a><p>Practical DevOps, cloud and AI coding tutorials.</p><a href="https://www.youtube.com/@Thetips4you" target="_blank" rel="noopener noreferrer">Visit the channel ↗</a></div></footer></body></html>'
def card(x):
    t='' if x['watch'] else ' target="_blank" rel="noopener noreferrer"'
    return f'''<a class="card" href="{e(link(x))}"{t}><span class="thumb"><img src="https://i.ytimg.com/vi/{e(x['id'])}/hqdefault.jpg" alt="Thumbnail for {e(x['title'])}" loading="lazy" width="480" height="360"><span class="play" aria-hidden="true">▶</span></span><span class="card-body"><span class="kicker">{e(x['category'])}</span><strong>{e(x['title'])}</strong><span class="desc">{e(x['summary'])}</span><span class="cta">{'Watch guide' if x['watch'] else 'Watch on YouTube'} ↗</span></span></a>'''
def crumbs(x):
    items=[('Home',D+'/'),('AI coding',D+'/ai-coding/')]
    if x: items.append((x['shortTitle'],D+link(x)))
    return {'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':i+1,'name':n,'item':u} for i,(n,u) in enumerate(items)]}
desc='Watch practical AI coding agent tutorials from Thetips4you: Claude Code with OpenRouter, OpenCode, Codex, agent skills, MCP, and more.'
body='''<section class="hero wrap"><p class="kicker">THE FIELD GUIDE / AI CODING</p><h1>Build with an <em>AI coding agent.</em></h1><p class="lead">Start with Claude Code or OpenCode. Then learn how tools, skills and model choices shape your workflow. Real tutorials from Thetips4you, organized so you can find the next step quickly.</p><div class="actions"><a class="button" href="#start">Choose a starting guide ↗</a><a href="#library">Browse all videos ↓</a></div><div class="index"><span>01 / SET UP</span><span>02 / COMPARE</span><span>03 / BUILD</span></div></section><section class="wrap section" id="start"><p class="kicker">START HERE</p><h2>Two ways into AI coding.</h2><p class="section-copy">Pick a tutorial and follow it alongside your own project.</p><div class="grid two">'''+''.join(card(x) for x in v[:2])+'''</div></section><section class="wrap section" id="library"><p class="kicker">KEEP EXPLORING</p><h2>More agent workflows.</h2><p class="section-copy">Compare tools, understand agent building blocks, and go deeper.</p><div class="grid">'''+''.join(card(x) for x in v[2:])+'''</div></section><section class="wrap explainer"><div><p class="kicker">THE BASICS</p><h2>What is an AI coding agent?</h2></div><div><p>An AI coding agent can work with project files and use tools to help plan, edit, and review code. The useful question is how it fits into your workflow: which model it uses, what actions it can take, and how you check the result.</p><p>These videos cover both the first setup and the pieces behind more capable agents. Start with a tool you can run, then explore skills, MCP connections, instruction files, and review workflows.</p><p class="note">Free model availability, limits, and pricing can change. Check each provider's current terms before choosing a setup.</p></div></section>'''
schema=[{'@context':'https://schema.org','@type':'CollectionPage','name':'AI Coding Agents & Tutorials','description':desc,'url':D+'/ai-coding/','publisher':{'@type':'Organization','name':'Thetips4you','url':D+'/'}},crumbs(None)]
(a/'index.html').write_text(head('AI Coding Agents & Tutorials | Thetips4you',desc,D+'/ai-coding/',schema=schema)+body+foot(),encoding='utf-8')
for x in v:
    if not x['watch']: continue
    folder=a/x['slug']; folder.mkdir(exist_ok=True)
    canonical=D+link(x); points=''.join('<li>'+e(z)+'</li>' for z in x['points'])
    related=''.join('<a href="'+e(link(y))+'">'+e(y['shortTitle'])+' ↗</a>' for y in v if y['watch'] and y['id']!=x['id'])
    note='<p class="note">Free model availability and usage limits can change. Check current provider terms when following the video.</p>' if x['id'] in ('GRUjApPqCoE','20vcJmqAr4M') else ''
    page=f'''<div class="wrap breadcrumbs"><a href="/">Home</a> / <a href="/ai-coding/">AI coding</a> / <span>{e(x['shortTitle'])}</span></div><article class="wrap watch"><p class="kicker">{e(x['category'])}</p><h1>{e(x['title'])}</h1><p class="lead">{e(x['summary'])}</p><div class="watch-grid"><div><div class="player"><iframe src="https://www.youtube-nocookie.com/embed/{e(x['id'])}" title="{e(x['title'])}" width="960" height="540" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><p class="caption">Prefer YouTube? <a href="https://www.youtube.com/watch?v={e(x['id'])}" target="_blank" rel="noopener noreferrer">Open this video on the Thetips4you channel ↗</a></p></div><aside class="lesson"><p class="kicker">IN THIS GUIDE</p><h2>What you'll explore</h2><ul>{points}</ul>{note}</aside></div><div class="related"><div><p class="kicker">CONTINUE LEARNING</p><h2>Keep building your workflow.</h2></div><div>{related}<a href="/ai-coding/">All AI coding guides ↗</a></div></div></article>'''
    video={'@context':'https://schema.org','@type':'VideoObject','name':x['title'],'description':x['summary'],'thumbnailUrl':'https://i.ytimg.com/vi/'+x['id']+'/hqdefault.jpg','uploadDate':x['published'],'embedUrl':'https://www.youtube-nocookie.com/embed/'+x['id'],'url':canonical,'publisher':{'@type':'Organization','name':'Thetips4you','url':D+'/'}}
    (folder/'index.html').write_text(head(x['title']+' | Thetips4you',x['summary'],canonical,image='https://i.ytimg.com/vi/'+x['id']+'/hqdefault.jpg',schema=[video,crumbs(x)])+page+foot(),encoding='utf-8')
urls=[D+'/',D+'/ai-coding/']+[D+link(x) for x in v if x['watch']]
(p/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('  <url><loc>'+e(u)+'</loc></url>\n' for u in urls)+'</urlset>\n',encoding='utf-8')
(p/'robots.txt').write_text('User-agent: *\nAllow: /llms.txt\nAllow: /agents.txt\nAllow: /\nSitemap: '+D+'/sitemap.xml\n',encoding='utf-8')
generate_llms()
print('Generated',len(urls),'sitemap URLs and',sum(x['watch'] for x in v),'watch pages')
